<div class="info-card"><h3>Informasi dari Admin <?php $unread=count(array_filter($pesan_itr,function($p){return !$p['dibaca_pada'];}));if($unread): ?><span class="tag"><?= $unread ?> baru</span><?php endif; ?></h3>
<?php if(!$pesan_itr): ?><p>Belum ada informasi dari admin. Pembaruan pengajuan akan tampil di sini.</p><?php endif; ?>
<?php foreach($pesan_itr as $p): ?><article style="padding:18px 0;border-bottom:1px solid var(--line)"><strong><?= htmlspecialchars($p['no_permohonan']) ?></strong><small style="display:block;color:var(--muted)"><?= htmlspecialchars($p['nama_admin']?:'Administrator') ?> · <?= date('d/m/Y H:i',strtotime($p['created_at'])) ?></small><p><?= nl2br(htmlspecialchars($p['isi'])) ?></p>
<?php if(!$p['dibaca_pada']): ?><?= form_open('pemohon/baca_pesan_itr/'.$p['id']) ?><input type="hidden" name="itr_token" value="<?= htmlspecialchars($this->session->userdata('itr_message_token'),ENT_QUOTES,'UTF-8') ?>"><button class="btn btn-ghost">Tandai Sudah Dibaca</button><?= form_close() ?><?php else: ?><small>Sudah dibaca pada <?= date('d/m/Y H:i',strtotime($p['dibaca_pada'])) ?></small><?php endif; ?></article><?php endforeach; ?></div>
